          "source_id": "P010",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies the feasibility condition and both assignment alternatives."
    }
  },
  "signal_basis": {
    "component_id": "C018.signal_basis",
    "value": "Compare first-publication outcomes after release within a predefined observation window. Valid random assignment, comparable follow-up and reliable outcome capture allow a publication difference to support an effect of the change.",
    "scope": "Proposed observations among eligible accounts over their intended roster opportunity; interpretation requires comparable linkage and capture and adequate evidence.",
